independent.solution:
questions = {"q1": "Is revenue on track?", "q2": "Which market is behind?", "q3": "Which customers drive revenue?"}
visuals = [
    {"name": "Revenue card", "answers": "q1"},
    {"name": "Trend line", "answers": "q1"},
    {"name": "Market bar", "answers": "q2"},
    {"name": "Animated globe", "answers": None},
    {"name": "Category donut", "answers": None},
    {"name": "Slicer panel", "answers": "q2"},
]
def audit(visuals, questions):
    return {
        "orphans": [v["name"] for v in visuals if v["answers"] not in questions],
        "uncovered": sorted(set(questions) - {v["answers"] for v in visuals}),
        "too_many": len(visuals) > 5,
    }

result = audit(visuals, questions)
for key in ["orphans", "uncovered", "too_many"]:
    print(f"{key}: {result[key]}")
